FormulaFieldDefinitions.FormulaFieldDefinition:
if {@Late Orders} > 10000 
then cdCurrencyScalerChoice (sum({@Late Orders}), "K", 0)
else cdCurrencyScalerChoice (sum({@Late Orders}), "K", 2)

whileprintingrecords;
if {@Required Date} - {@Received Date} < 0
then stringvar lateorders:= lateorders + totext({Orders.Order_ID},0,"") + "^";
lateorders

if sum({@On-Time Orders}) > 100000
then cdCurrencyScalerChoice (sum({@On-Time Orders}), "M", 2)
else cdCurrencyScalerChoice (sum({@On-Time Orders}), "K", 1)

if Sum ({Orders.Order_Amount}, {@Group 1}) > 10000 
then cdCurrencyScalerChoice (Sum ({Orders.Order_Amount}, {@Group 1}), "K", 0)
else cdCurrencyScalerChoice (Sum ({Orders.Order_Amount}, {@Group 1}), "K", 2)

// a formula is used to create this DateTime field as the Xtreme sample data contains only 12:00:00 as a time

datetimevar receiveddate:= 
date(dateadd("d", Int(1.1/Rnd), {Orders.Ship_Date})) + 
time((Int(Rnd*24)), (Int(Rnd*59)), 0);

if receiveddate <= {@Order Date} then {@Order Date} + 4 else receiveddate

// a formula is used to create this DateTime field as the Xtreme sample data contains only 12:00:00 as a time

datetimevar requireddate:= 
date({Orders.Required_Date}) + 
time((Int(Rnd*24)), 0, 0);

if requireddate <= {@Order Date} then datetime(date({@Order Date}) + 2, time(12,00,00)) else requireddate

CustomFunction.Text:
Function (datetimevar startdate, datetimevar enddate)


if enddate - startdate > 0 then
(
numbervar ds:= (date(enddate) - date(startdate))*86400;
numbervar hs:= (hour(enddate) - hour(startdate))*3600;
numbervar ms:= (minute(enddate) - minute(startdate))*60;
numbervar ss:= second(enddate) - second(startdate);
numbervar ts:= ds+hs+ms+ss;

ds:= truncate(ts/86400);
hs:= truncate((remainder(ts,86400))/3600);
ms:= truncate((remainder(ts,3600))/60);
ss:= truncate(remainder(ts,60));

stringvar dsd;
stringvar hsd;
stringvar msd;
stringvar ssd;

if ds < 10 then dsd:= "0" + totext(ds,0,"") else dsd:= totext(ds,0,"");
if hs < 10 then hsd:= "0" + totext(hs,0,"") else hsd:= totext(hs,0,"");
if ms < 10 then msd:= "0" + totext(ms,0,"") else msd:= totext(ms,0,"");
if ss < 10 then ssd:= "0" + totext(ss,0,"") else ssd:= totext(ss,0,"");

stringvar display:= " " + dsd + ":" + hsd + ":" + msd + ":" + ssd;
)

else

(
numbervar ds:= (date(startdate) - date(enddate))*86400;
numbervar hs:= (hour(startdate) - hour(enddate))*3600;
numbervar ms:= (minute(startdate) - minute(enddate))*60;
numbervar ss:= second(startdate) - second(enddate);
numbervar ts:= ds+hs+ms+ss;

ds:= truncate(ts/86400);
hs:= truncate((remainder(ts,86400))/3600);
ms:= truncate((remainder(ts,3600))/60);
ss:= truncate(remainder(ts,60));

stringvar dsd;
stringvar hsd;
stringvar msd;
stringvar ssd;

if ds < 10 then dsd:= "0" + totext(ds,0,"") else dsd:= totext(ds,0,"");
if hs < 10 then hsd:= "0" + totext(hs,0,"") else hsd:= totext(hs,0,"");
if ms < 10 then msd:= "0" + totext(ms,0,"") else msd:= totext(ms,0,"");
if ss < 10 then ssd:= "0" + totext(ss,0,"") else ssd:= totext(ss,0,"");

stringvar display:= "-" + dsd + ":" + hsd + ":" + msd + ":" + ssd;
);

display;
